def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = [float(x) for x in history if math.isfinite(float(x))]
    if horizon <= 0:
        return []
    if not h:
        return [0.0] * horizon
    period = 24 if 'hour' in frequency.lower() else max(1, min(7, len(h)))
    cycles = []
    end = len(h)
    while end >= period and len(cycles) < 6:
        cycles.append(h[end-period:end])
        end -= period
    cycles.reverse()
    if not cycles:
        return [float(max(0.0, h[-1]))] * horizon
    template = []
    for p in range(period):
        vals = [c[p] for c in cycles]
        active = sum(1 for v in vals if v > 0.0)
        if active * 2 < len(vals):
            template.append(0.0)
        else:
            positive = [v for v in vals if v > 0.0]
            template.append(float(statistics.median(positive)) if positive else 0.0)
    return [float(max(0.0, template[k % period])) for k in range(horizon)]
